def transform(grid):
    out = [row[:] for row in grid]
    # The 9-shaped object functions as a stencil: matching 5s in its
    # pattern are recolored to 6.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                out[r][c] = 6
    return out
